const AS = (n) => `${R}/android_studio/${n}.jpg`;
const UML = (n) => `${R}/uml/${n}.png`;
const EV = (n) => `${R}/evidencias/${n}.jpg`;
const REPO = 'https://github.com/NX-Systems-svg/GodziPet90';

const h1 = (t) => ({ t: 'h1', v: t });
const h2 = (t) => ({ t: 'h2', v: t });
const p = (t) => ({ t: 'p', v: t });
const ul = (...a) => ({ t: 'ul', v: a });
const nota = (t) => ({ t: 'nota', v: t });
const img = (src, ancho, pie) => ({ t: 'img', src, ancho, pie });
const tabla = (cols, enc, filas) => ({ t: 'tabla', cols, enc, filas });
const salto = () => ({ t: 'salto' });
const galeria = (items, ancho, porFila) => ({ t: 'galeria', items, ancho, porFila });
const land = (...v) => ({ t: 'land', v });
const F = (k) => {
  const f = FR[k];
  if (!f) throw new Error('Fragmento no encontrado: ' + k);
  return { t: 'codigo', titulo: `app/src/main/java/com/cesba/godzipet/${f.ruta}  ·  líneas ${f.ini}–${f.fin}`, v: f.v };
};
const prueba = (o) => ({ t: 'prueba', ...o });

// Explicación estándar de un fragmento: propósito, variables, operaciones, resultado.
const explica = (proposito, variables, operaciones, resultado) => tabla([1.3, 5.2], ['Aspecto', 'Explicación'], [
  ['**Propósito**', proposito], ['**Variables**', variables], ['**Operaciones**', operaciones], ['**Resultado esperado**', resultado]]);

// Ficha de un método (sección 7).
const metodo = (n, nombre, proposito, params, ret, proceso, resultado, k) => [
  h2(`7.${n} ${nombre}`),
  tabla([1.4, 5.1], ['Elemento', 'Descripción'], [
    ['**Nombre**', nombre], ['**Propósito**', proposito], ['**Parámetros de entrada**', params], ['**Tipo de retorno**', ret],
    ['**Proceso que realiza**', proceso], ['**Resultado esperado**', resultado]]),
  F(k),
];

